// Transport: Aktennummer aus Betreff oder Text, Anhänge als Base64. Das
// Muster ist die Form der Akten-Kennung (ZP-JJJJ-NNNN); mehr Zuordnung wäre
// eine Regel und gehörte nach src/ (ADR-010, "Wann wir anders entscheiden").
const alle = $input.all();
const aus = [];
for (let i = 0; i < alle.length; i += 1) {
  const j = alle[i].json;
  const text = [j.subject, j.textPlain, j.text].filter(Boolean).join('\n');
  const treffer = text.match(/ZP-\d{4}-\d{4}/);
  const dateien = [];
  for (const [schluessel, binaer] of Object.entries(alle[i].binary ?? {})) {
    if (!schluessel.startsWith('attachment_')) continue;
    const puffer = await this.helpers.getBinaryDataBuffer(i, schluessel);
    dateien.push({ name: binaer.fileName ?? `${schluessel}.pdf`, inhalt_base64: puffer.toString('base64') });
  }
  const grund = !treffer ? 'keine Aktennummer in Betreff oder Text' : dateien.length === 0 ? 'keine Anhänge' : null;
  aus.push({ json: {
    akte_id: treffer ? treffer[0] : null,
    von: typeof j.from === 'string' ? j.from : (j.from?.text ?? null),
    betreff: j.subject ?? null,
    mail_id: j.messageId ?? j.metadata?.['message-id'] ?? null,
    anhaenge: dateien.length,
    zugeordnet: grund === null,
    grund,
    dateien,
  } });
}
return aus;

// Transport: Was die Extraktion braucht (Stammdaten und die neuen Dateien),
// und daneben, was die Zusammenführung danach braucht (die abgelegte Akte
// und die Mail). Der Extraktions-Node behält nur seine eigene Ausgabe;
// deshalb liest die Zusammenführung dieses Item über den Node-Namen.
return $input.all().map((item) => {
  const e = item.json;
  return { json: {
    akte: e.stammdaten ?? {},
    dateien: e.eingang?.dateien ?? [],
    abgelegt: { akte_id: e.akte_id, stammdaten: e.stammdaten ?? {}, dokumente: e.dokumente ?? [], assertions: e.assertions ?? [] },
    mail: { von: e.eingang?.von ?? null, betreff: e.eingang?.betreff ?? null, mail_id: e.eingang?.mail_id ?? null, anhaenge: e.eingang?.anhaenge ?? 0 },
  } };
});

// Transport (ADR-010): Die neuen Belege bekommen eine Kennung mit Suffix
// -E<n>, damit sie neben den alten stehen; Assertions werden mit umbenannt.
// Ein Anhang, dessen Hash die Akte schon kennt, wird nicht noch einmal
// angehängt. Welche Aussage danach gilt, entscheidet das Regelwerk.
const neu = $input.first().json;
const vor = $('Extraktion vorbereiten').first().json;
const alt = vor.abgelegt;
const bekannteHashes = new Set((alt.dokumente ?? []).map((d) => d.hash).filter(Boolean));
const lauf = (alt.dokumente ?? []).filter((d) => /-E\d+$/.test(d.id)).length + 1;
const umbenannt = new Map();
const neueDokumente = [];
for (const d of neu.dokumente ?? []) {
  if (d.hash && bekannteHashes.has(d.hash)) continue;
  const id = `${d.id}-E${lauf}`;
  umbenannt.set(d.id, id);
  neueDokumente.push({ ...d, id, quelle: 'mail' });
}
const neueAssertions = (neu.assertions ?? []).filter((a) => umbenannt.has(a.dokument)).map((a) => ({ ...a, dokument: umbenannt.get(a.dokument) }));
return [{ json: {
  ...alt.stammdaten,
  akte_id: alt.akte_id,
  quelle: 'mail',
  dokumente: [...(alt.dokumente ?? []), ...neueDokumente],
  assertions: [...(alt.assertions ?? []), ...neueAssertions],
  extraktion: neu.extraktion ?? null,
  eingang: { ...vor.mail, neue_belege: neueDokumente.map((d) => d.id) },
} }];
